theorem pressure_le_mass {g a : ℝ → ℝ} {A : ℝ}
    (h : Admissible g a A) (η : ℝ) :
    pressure g a η ≤ -(1 / 2 : ℝ) * kernel A η * ∫ y, g y

theorem integration_by_parts {f g : Space → ℝ}
    (hf : ContDiff ℝ 1 f) (hg : ContDiff ℝ 1 g) (hs : HasCompactSupport f) (i : Fin 3) :
    (∫ x : Space, f x * spatialPartial i g x) = -(∫ x : Space, spatialPartial i f x * g x)

theorem weightedDerivativeNorm_memLp {φ : Space → ℝ} {w : Space → Space}
    (hφ : ContDiff ℝ 1 φ) (hc : HasCompactSupport φ) (hw : ContDiff ℝ 1 w) :
    MemLp (weightedDerivativeNorm φ w) 2

theorem kernel_le_gamma {a : ℝ} (ha : 1 < a) (n : ℕ) {z v : ℝ}
    (hz : 0 ≤ z) (hv : 0 < v) :
    kernel a n z v ≤ Real.exp (-v) * v ^ (a + (n : ℝ) - 1)

theorem kernel_norm_le_gamma {a : ℝ} (ha : 1 < a) (n : ℕ) {z v : ℝ}
    (hz : 0 ≤ z) (hv : 0 < v) :
    ‖kernel a n z v‖ ≤ Real.exp (-v) * v ^ (a + (n : ℝ) - 1)

theorem hasFDerivAt_extendTrace [NormedSpace ℝ V] {T : ℝ} {f : SpaceTime → V} {L : Space → V}
    {z : SpaceTime} {f' : SpaceTime →L[ℝ] V} (hz : z.1 < T)
    (hf : HasFDerivAt f f' z) : HasFDerivAt (extendTrace T f L) f' z

theorem parameterIntegral_contDiff [CompleteSpace G] {g : H × ℝ → G}
    (hg : ContDiff ℝ ∞ g) (a b : ℝ) :
    ContDiff ℝ ∞ (fun y => ∫ u in a..b, g (y, u))

theorem shifted_integrable {a b M : ℝ} {v : E} {f : ℝ × E → F}
    (hf : Continuous f) (hs : RadialAlias.RadiallySupported a b f) (z : ℝ × E) :
    Integrable (fun u => f (shift M v z u))
